12 // AXI RISC-V LR/SC Adapter
13 //
14 // This adapter adds support for AXI4 exclusive accesses to a slave that natively does not support
15 // exclusive accesses.  It is to be placed between that slave and the upstream master port, so that
16 // the `mst` port of this module drives the slave and the `slv` port of this module is driven by
17 // the upstream master.
18 //
19 // Exclusive accesses are only enabled for a range of addresses specified through parameters.  All
20 // addresses within that range are guaranteed to fulfill the constraints described in A7.2 of the
21 // AXI4 standard, both for normal and exclusive memory accesses.  Addresses outside that range
22 // behave like a slave that does not support exclusive memory accesses (see AXI4, A7.2.5).
23 //
24 // Limitations:
25 //  -   The adapter does not support bursts in exclusive accessing.  Only single words can be
26 //      reserved.
27 //
28 // Maintainer: Andreas Kurth <akurth@iis.ee.ethz.ch>
29 
30 module axi_riscv_lrsc #(
31     /// Exclusively-accessible address range (closed interval from ADDR_BEGIN to ADDR_END)
32     parameter longint unsigned ADDR_BEGIN = 0,
33     parameter longint unsigned ADDR_END = 0,
34     /// AXI Parameters
35     parameter int unsigned AXI_ADDR_WIDTH = 0,
36     parameter int unsigned AXI_DATA_WIDTH = 0,
37     parameter int unsigned AXI_ID_WIDTH = 0,
38     parameter int unsigned AXI_USER_WIDTH = 0,
39     parameter int unsigned AXI_MAX_READ_TXNS = 0,  // Maximum number of in-flight read transactions
40     parameter int unsigned AXI_MAX_WRITE_TXNS = 0, // Maximum number of in-flight write transactions
41     parameter bit AXI_USER_AS_ID = 1'b0,           // Use the AXI User signal instead of the AXI ID to track reservations
42     parameter int unsigned AXI_USER_ID_MSB = 0,    // MSB of the ID in the user signal
43     parameter int unsigned AXI_USER_ID_LSB = 0,    // LSB of the ID in the user signal
44     parameter int unsigned AXI_ADDR_LSB = $clog2(AXI_DATA_WIDTH/8), // log2 of granularity for reservations (ignored LSBs)
45     /// Enable debug prints (not synthesizable).
46     parameter bit DEBUG = 1'b0,
47     /// Derived Parameters (do NOT change manually!)
48     localparam int unsigned AXI_STRB_WIDTH = AXI_DATA_WIDTH / 8
49 ) (
50     input logic                         clk_i,
51     input logic                         rst_ni,
52 
53     /// Slave Interface
54     input  logic [AXI_ADDR_WIDTH-1:0]   slv_aw_addr_i,
55     input  logic [2:0]                  slv_aw_prot_i,
56     input  logic [3:0]                  slv_aw_region_i,
57     input  logic [5:0]                  slv_aw_atop_i,
58     input  logic [7:0]                  slv_aw_len_i,
59     input  logic [2:0]                  slv_aw_size_i,
60     input  logic [1:0]                  slv_aw_burst_i,
61     input  logic                        slv_aw_lock_i,
62     input  logic [3:0]                  slv_aw_cache_i,
63     input  logic [3:0]                  slv_aw_qos_i,
64     input  logic [AXI_ID_WIDTH-1:0]     slv_aw_id_i,
65     input  logic [AXI_USER_WIDTH-1:0]   slv_aw_user_i,
66     output logic                        slv_aw_ready_o,
67     input  logic                        slv_aw_valid_i,
68 
69     input  logic [AXI_ADDR_WIDTH-1:0]   slv_ar_addr_i,
70     input  logic [2:0]                  slv_ar_prot_i,
71     input  logic [3:0]                  slv_ar_region_i,
72     input  logic [7:0]                  slv_ar_len_i,
73     input  logic [2:0]                  slv_ar_size_i,
74     input  logic [1:0]                  slv_ar_burst_i,
75     input  logic                        slv_ar_lock_i,
76     input  logic [3:0]                  slv_ar_cache_i,
77     input  logic [3:0]                  slv_ar_qos_i,
78     input  logic [AXI_ID_WIDTH-1:0]     slv_ar_id_i,
79     input  logic [AXI_USER_WIDTH-1:0]   slv_ar_user_i,
80     output logic                        slv_ar_ready_o,
81     input  logic                        slv_ar_valid_i,
82 
83     input  logic [AXI_DATA_WIDTH-1:0]   slv_w_data_i,
84     input  logic [AXI_STRB_WIDTH-1:0]   slv_w_strb_i,
85     input  logic [AXI_USER_WIDTH-1:0]   slv_w_user_i,
86     input  logic                        slv_w_last_i,
87     output logic                        slv_w_ready_o,
88     input  logic                        slv_w_valid_i,
89 
90     output logic [AXI_DATA_WIDTH-1:0]   slv_r_data_o,
91     output logic [1:0]                  slv_r_resp_o,
92     output logic                        slv_r_last_o,
93     output logic [AXI_ID_WIDTH-1:0]     slv_r_id_o,
94     output logic [AXI_USER_WIDTH-1:0]   slv_r_user_o,
95     input  logic                        slv_r_ready_i,
96     output logic                        slv_r_valid_o,
97 
98     output logic [1:0]                  slv_b_resp_o,
99     output logic [AXI_ID_WIDTH-1:0]     slv_b_id_o,
100     output logic [AXI_USER_WIDTH-1:0]   slv_b_user_o,
101     input  logic                        slv_b_ready_i,
102     output logic                        slv_b_valid_o,
103 
104     /// Master Interface
105     output logic [AXI_ADDR_WIDTH-1:0]   mst_aw_addr_o,
106     output logic [2:0]                  mst_aw_prot_o,
107     output logic [3:0]                  mst_aw_region_o,
108     output logic [5:0]                  mst_aw_atop_o,
109     output logic [7:0]                  mst_aw_len_o,
110     output logic [2:0]                  mst_aw_size_o,
111     output logic [1:0]                  mst_aw_burst_o,
112     output logic                        mst_aw_lock_o,
113     output logic [3:0]                  mst_aw_cache_o,
114     output logic [3:0]                  mst_aw_qos_o,
115     output logic [AXI_ID_WIDTH-1:0]     mst_aw_id_o,
116     output logic [AXI_USER_WIDTH-1:0]   mst_aw_user_o,
117     input  logic                        mst_aw_ready_i,
118     output logic                        mst_aw_valid_o,
119 
120     output logic [AXI_ADDR_WIDTH-1:0]   mst_ar_addr_o,
121     output logic [2:0]                  mst_ar_prot_o,
122     output logic [3:0]                  mst_ar_region_o,
123     output logic [7:0]                  mst_ar_len_o,
124     output logic [2:0]                  mst_ar_size_o,
125     output logic [1:0]                  mst_ar_burst_o,
126     output logic                        mst_ar_lock_o,
127     output logic [3:0]                  mst_ar_cache_o,
128     output logic [3:0]                  mst_ar_qos_o,
129     output logic [AXI_ID_WIDTH-1:0]     mst_ar_id_o,
130     output logic [AXI_USER_WIDTH-1:0]   mst_ar_user_o,
131     input  logic                        mst_ar_ready_i,
132     output logic                        mst_ar_valid_o,
133 
134     output logic [AXI_DATA_WIDTH-1:0]   mst_w_data_o,
135     output logic [AXI_STRB_WIDTH-1:0]   mst_w_strb_o,
136     output logic [AXI_USER_WIDTH-1:0]   mst_w_user_o,
137     output logic                        mst_w_last_o,
138     input  logic                        mst_w_ready_i,
139     output logic                        mst_w_valid_o,
140 
141     input  logic [AXI_DATA_WIDTH-1:0]   mst_r_data_i,
142     input  logic [1:0]                  mst_r_resp_i,
143     input  logic                        mst_r_last_i,
144     input  logic [AXI_ID_WIDTH-1:0]     mst_r_id_i,
145     input  logic [AXI_USER_WIDTH-1:0]   mst_r_user_i,
146     output logic                        mst_r_ready_o,
147     input  logic                        mst_r_valid_i,
148 
149     input  logic [1:0]                  mst_b_resp_i,
150     input  logic [AXI_ID_WIDTH-1:0]     mst_b_id_i,
151     input  logic [AXI_USER_WIDTH-1:0]   mst_b_user_i,
152     output logic                        mst_b_ready_o,
153     input  logic                        mst_b_valid_i
154 );
155 
156     // Declarations of Signals and Types
157     localparam int unsigned RES_ID_WIDTH = AXI_USER_AS_ID ?
158             AXI_USER_ID_MSB - AXI_USER_ID_LSB + 1
159             : AXI_ID_WIDTH;
160 
161     typedef logic [AXI_ADDR_WIDTH-1:0]               axi_addr_t;
162     typedef logic [AXI_DATA_WIDTH-1:0]               axi_data_t;
163     typedef logic [AXI_ID_WIDTH-1:0]                 axi_id_t;
164     typedef logic [1:0]                              axi_resp_t;
165     typedef logic [AXI_USER_WIDTH-1:0]               axi_user_t;
166     typedef logic [AXI_ADDR_WIDTH-AXI_ADDR_LSB-1:0]  res_addr_t; // Track reservations with given granularity.
167     typedef logic [RES_ID_WIDTH-1:0]                 res_id_t;
168 
169     typedef enum logic [1:0] {
170         B_REGULAR='0, B_EXCLUSIVE, B_INJECT
171     } b_cmd_t;
172 
173     typedef struct packed {
174         axi_id_t    id;
175         axi_user_t  user;
176     } b_inj_t;
177 
178     typedef struct packed {
179         axi_id_t    id;
180         axi_user_t  user;
181         axi_resp_t  resp;
182     } b_chan_t;
183 
184     typedef struct packed {
185         axi_id_t    id;
186         axi_data_t  data;
187         axi_resp_t  resp;
188         axi_user_t  user;
189         logic       last;
190     } r_chan_t;
191 
192     typedef struct packed {
193         logic   excl;
194     } r_flight_t;
195 
196     typedef struct packed {
197         logic       forward;
198         axi_id_t    id;
199         axi_user_t  user;
200     } w_cmd_t;
201 
202     typedef struct packed {
203         res_addr_t  addr;
204         logic       excl;
205     } w_flight_t;
206 
207     typedef struct packed {
208         w_flight_t                      data;
209         logic [$bits(w_flight_t)-1:0]   mask;
210     } wifq_exists_t;
211 
212     typedef enum logic {
213         AR_IDLE, AR_WAIT
214     } ar_state_t;
215 
216     typedef enum logic [1:0] {
217         AW_IDLE, AW_WAIT, AW_BURST
218     } aw_state_t;
219 
220     typedef struct packed {
221         axi_addr_t  addr;
222         logic [2:0] prot;
223         logic [3:0] region;
224         logic [5:0] atop;
225         logic [7:0] len;
226         logic [2:0] size;
227         logic [1:0] burst;
228         logic [3:0] cache;
229         logic [3:0] qos;
230         axi_id_t    id;
231         axi_user_t  user;
232     } aw_chan_t;
233 
234     typedef enum logic {
235         B_NORMAL, B_FORWARD
236     } b_state_t;
237 
238     axi_id_t        b_status_inp_id,
239                     b_status_oup_id,
240                     rifq_oup_id;
241 
242     res_addr_t      ar_push_addr,
243                     art_check_clr_addr;
244 
245     res_id_t        art_set_id,
246                     art_check_id;
247 
248     logic           ar_push_excl,
249                     ar_push_res;
250 
251     logic           art_check_clr_excl;
252 
253     logic           ar_push_valid,              ar_push_ready,
254                     art_check_clr_req,          art_check_clr_gnt,
255                     art_filter_valid,           art_filter_ready,
256                     art_set_req,                art_set_gnt;
257 
258     logic           rifq_inp_req,               rifq_inp_gnt,
259                     rifq_oup_req,               rifq_oup_gnt,
260                     rifq_oup_pop,
261                     rifq_oup_data_valid;
262 
263     r_flight_t      rifq_inp_data,
264                     rifq_oup_data;
265 
266     logic           wifq_exists,
267                     ar_wifq_exists_req,         ar_wifq_exists_gnt,
268                     aw_wifq_exists_req,         aw_wifq_exists_gnt,
269                     wifq_exists_req,            wifq_exists_gnt,
270                                                 wifq_inp_gnt,
271                     wifq_oup_req,               wifq_oup_gnt,
272                     wifq_oup_data_valid;
273 
274     wifq_exists_t   ar_wifq_exists_inp,
275                     aw_wifq_exists_inp,
276                     wifq_exists_inp;
277 
278     b_chan_t        slv_b;
279 
280     logic           slv_b_valid,                slv_b_ready;
281 
282     r_chan_t        slv_r;
283 
284     logic           slv_r_valid,                slv_r_ready;
285 
286     logic           mst_b_valid,                mst_b_ready;
287 
288     w_cmd_t         w_cmd_inp,                  w_cmd_oup;
289 
290     logic           w_cmd_push,                 w_cmd_pop,
291                     w_cmd_full,                 w_cmd_empty;
292 
293     b_inj_t         b_inj_inp,                  b_inj_oup;
294 
295     logic           b_inj_push,                 b_inj_pop,
296                     b_inj_full,                 b_inj_empty;
297 
298     b_cmd_t         b_status_inp_cmd,           b_status_oup_cmd;
299 
300     logic           b_status_inp_req,           b_status_oup_req,
301                     b_status_inp_gnt,           b_status_oup_gnt,
302                     b_status_oup_pop,
303                     b_status_oup_valid;
304 
305     logic           art_check_res;
306 
307     ar_state_t      ar_state_d,                 ar_state_q;
308 
309     aw_state_t      aw_state_d,                 aw_state_q;
310 
311     b_state_t       b_state_d,                  b_state_q;
312 
313     aw_chan_t       slv_aw,                     mst_aw;
314 
315     logic           mst_aw_valid,               mst_aw_ready;
316 
317     res_addr_t      clr_addr_d,                 clr_addr_q;
318 
319     res_id_t        clr_id_d,                   clr_id_q;
320 
321     // 3 bits AxSIZE + 8 bits AxLEN - ignored LSBs
322     logic [10-AXI_ADDR_LSB:0] clr_len_d,        clr_len_q,
323                               aw_res_len;
324 
325     logic           aw_wait_d,                  aw_wait_q;
326 
327     // AR and R Channel
328 
329     // IQ Queue to track in-flight reads
330     id_queue #(
331         .ID_WIDTH   (AXI_ID_WIDTH),
332         .CAPACITY   (AXI_MAX_READ_TXNS),
333         .data_t     (r_flight_t),
334         .FULL_BW    (1'b1)
335     ) i_read_in_flight_queue (
336         .clk_i              (clk_i),
337         .rst_ni             (rst_ni),
338         .inp_id_i           (slv_ar_id_i),
339         .inp_data_i         (rifq_inp_data),
340         .inp_req_i          (rifq_inp_req),
341         .inp_gnt_o          (rifq_inp_gnt),
342         .exists_data_i      (),
343         .exists_mask_i      (),
344         .exists_req_i       (1'b0),
345         .exists_o           (),
346         .exists_gnt_o       (),
347         .oup_id_i           (rifq_oup_id),
348         .oup_pop_i          (rifq_oup_pop),
349         .oup_req_i          (rifq_oup_req),
350         .oup_data_o         (rifq_oup_data),
351         .oup_data_valid_o   (rifq_oup_data_valid),
352         .oup_gnt_o          (rifq_oup_gnt)
353     );
354     assign rifq_inp_data.excl = ar_push_excl;
355 
356     // Fork requests from AR into reservation table and queue of in-flight reads.
357     stream_fork #(
358         .N_OUP  (2)
359     ) i_ar_push_fork (
360         .clk_i      (clk_i),
361         .rst_ni     (rst_ni),
362         .valid_i    (ar_push_valid),
363         .ready_o    (ar_push_ready),
364         .valid_o    ({art_filter_valid, rifq_inp_req}),
365         .ready_i    ({art_filter_ready, rifq_inp_gnt})
366     );
367 
368     stream_filter i_art_filter (
369         .valid_i    (art_filter_valid),
370         .ready_o    (art_filter_ready),
371         .drop_i     (!ar_push_res),
372         .valid_o    (art_set_req),
373         .ready_i    (art_set_gnt)
374     );
375 
376     // Time-Invariant Signal Assignments
377     assign mst_ar_addr_o    = slv_ar_addr_i;
378     assign mst_ar_prot_o    = slv_ar_prot_i;
379     assign mst_ar_region_o  = slv_ar_region_i;
380     assign mst_ar_len_o     = slv_ar_len_i;
381     assign mst_ar_size_o    = slv_ar_size_i;
382     assign mst_ar_burst_o   = slv_ar_burst_i;
383     assign mst_ar_lock_o    = 1'b0;
384     assign mst_ar_cache_o   = slv_ar_cache_i;
385     assign mst_ar_qos_o     = slv_ar_qos_i;
386     assign mst_ar_id_o      = slv_ar_id_i;
387     assign mst_ar_user_o    = slv_ar_user_i;
388     assign slv_r.data       = mst_r_data_i;
389     assign slv_r.last       = mst_r_last_i;
390     assign slv_r.id         = mst_r_id_i;
391     assign slv_r.user       = mst_r_user_i;
392 
393     // Control R Channel
394     always_comb begin
395         mst_r_ready_o   = 1'b0;
396         slv_r.resp      = '0;
397         slv_r_valid     = 1'b0;
398         rifq_oup_id     = '0;
399         rifq_oup_pop    = 1'b0;
400         rifq_oup_req    = 1'b0;
401         if (mst_r_valid_i && slv_r_ready) begin
402             rifq_oup_id     = mst_r_id_i;
403             rifq_oup_pop    = mst_r_last_i;
404             rifq_oup_req    = 1'b1;
405             if (rifq_oup_gnt) begin
406                 mst_r_ready_o = 1'b1;
407                 if (mst_r_resp_i[1] == 1'b0) begin
408                     slv_r.resp = {1'b0, rifq_oup_data.excl};
409                 end else begin
410                     slv_r.resp = mst_r_resp_i;
411                 end
412                 slv_r_valid = 1'b1;
413             end
414         end
415     end
416 
417 // pragma translate_off
418     always @(posedge clk_i) begin
419         if (~rst_ni) begin
420             if (rifq_oup_req && rifq_oup_gnt) begin
421                 assert (rifq_oup_data_valid) else $error("Unexpected R with ID %0x!", mst_r_id_i);
422             end
423         end
424     end
425 // pragma translate_on
426 
427     // Control AR Channel
428     always_comb begin
429         mst_ar_valid_o                  = 1'b0;
430         slv_ar_ready_o                  = 1'b0;
431         ar_push_addr                    = '0;
432         ar_push_excl                    = '0;
433         ar_push_res                     = '0;
434         ar_push_valid                   = 1'b0;
435         ar_wifq_exists_inp.data.addr    = '0;
436         ar_wifq_exists_inp.data.excl    = 1'b0;
437         ar_wifq_exists_inp.mask         = '1;
438         ar_wifq_exists_inp.mask[12:0]   = '0; // Don't care on `excl` bit and page offset.
439         ar_wifq_exists_req              = 1'b0;
440         ar_state_d                      = ar_state_q;
441 
442         case (ar_state_q)
443 
444             AR_IDLE: begin
445                 if (slv_ar_valid_i) begin
446                     ar_push_addr = slv_ar_addr_i[AXI_ADDR_WIDTH-1:AXI_ADDR_LSB];
447                     ar_push_excl = (slv_ar_addr_i >= ADDR_BEGIN && slv_ar_addr_i <= ADDR_END &&
448                             slv_ar_lock_i && slv_ar_len_i == 8'h00);
449                     if (ar_push_excl) begin
450                         ar_wifq_exists_inp.data.addr = slv_ar_addr_i[AXI_ADDR_WIDTH-1:AXI_ADDR_LSB];
451                         ar_wifq_exists_req = 1'b1;
452                         if (ar_wifq_exists_gnt) begin
453                             ar_push_res = !wifq_exists;
454                             ar_push_valid = 1'b1;
455                         end
456                     end else begin
457                         ar_push_res = 1'b0;
458                         ar_push_valid = 1'b1;
459                     end
460                     if (ar_push_ready) begin
461                         mst_ar_valid_o = 1'b1;
462                         if (mst_ar_ready_i) begin
463                             slv_ar_ready_o = 1'b1;
464                         end else begin
465                             ar_state_d = AR_WAIT;
466                         end
467                     end
468                 end
469             end
470 
471             AR_WAIT: begin
472                 mst_ar_valid_o = slv_ar_valid_i;
473                 slv_ar_ready_o = mst_ar_ready_i;
474                 if (mst_ar_ready_i && mst_ar_valid_o) begin
475                     ar_state_d = AR_IDLE;
476                 end
477             end
478 
479             default: begin
480                 ar_state_d = AR_IDLE;
481             end
482         endcase
483     end
484 
485     // AW, W and B Channel
486 
487     // FIFO to track commands for W bursts.
488     fifo_v3 #(
489         .FALL_THROUGH   (1'b0), // There would be a combinatorial loop if this were a fall-through
490                                 // register.  Optimizing this can reduce the latency of this module.
491         .dtype          (w_cmd_t),
492         .DEPTH          (AXI_MAX_WRITE_TXNS)
493     ) i_w_cmd_fifo (
494         .clk_i      (clk_i),
495         .rst_ni     (rst_ni),
496         .flush_i    (1'b0),
497         .testmode_i (1'b0),
498         .full_o     (w_cmd_full),
499         .empty_o    (w_cmd_empty),
500         .usage_o    (),
501         .data_i     (w_cmd_inp),
502         .push_i     (w_cmd_push),
503         .data_o     (w_cmd_oup),
504         .pop_i      (w_cmd_pop)
505     );
506 
507     // ID Queue to track downstream W bursts and their pending B responses.
508     // Workaround for bug in Questa (at least 2018.07 is affected) and VCS (at least 2020.12 is
509     // affected):
510     // Flatten the enum into a logic vector before using that type when instantiating `id_queue`.
511     typedef logic [$bits(b_cmd_t)-1:0] b_cmd_flat_t;
512     b_cmd_flat_t b_status_inp_cmd_flat, b_status_oup_cmd_flat;
513     assign b_status_inp_cmd_flat = b_cmd_flat_t'(b_status_inp_cmd);
514     id_queue #(
515         .ID_WIDTH   (AXI_ID_WIDTH),
516         .CAPACITY   (AXI_MAX_WRITE_TXNS),
517         .data_t     (b_cmd_flat_t),
518         .FULL_BW    (1'b1)
519     ) i_b_status_queue (
520         .clk_i              (clk_i),
521         .rst_ni             (rst_ni),
522         .inp_id_i           (b_status_inp_id),
